export type BankingDetails = {
  accountNumber: string;
  branchCode: string;
  branchLabel: string;
};

/**
 * Registration EFT details supplied by Mobsie Kids. The reference is the
 * application reference generated by the API, not the account number.
 */
export function bankingDetailsForBranch(branchName?: string | null): BankingDetails | null {
  const name = (branchName ?? '').toLowerCase();

  if (name.includes('soshanguve')) {
    return {
      accountNumber: '6311 5075 920',
      branchCode: name.includes('2') ? 'S2' : 'S1',
      branchLabel: 'Soshanguve',
    };
  }
  if (name.includes('mamelodi')) {
    return { accountNumber: '6311 4977 036', branchCode: 'M1', branchLabel: 'Mamelodi' };
  }
  if (name.includes('cosmo')) {
    return { accountNumber: '6311 5074 394', branchCode: 'C1', branchLabel: 'Cosmo City' };
  }
  if (name.includes('sky')) {
    return { accountNumber: '6311 507 5508', branchCode: 'SC1', branchLabel: 'Sky City' };
  }
  return null;
}
